import React, { useState } from "react";

import Hero from "../components/Hero";
import Marquee from "../components/Marquee";
import Collections from "../components/Collections";
import Shop from "../components/Shop";
import Craft from "../components/Craft";
import Process from "../components/Process";
import Testimonials from "../components/Testimonials";
import FAQ from "../components/FAQ";
import FinalCTA from "../components/FinalCTA";

export default function Home({ filter, setFilter, addToCart, scrollTo }) {
  const [activeCollection, setActiveCollection] = useState("Rings");
  const [faqOpen, setFaqOpen] = useState(0);
  const [testimonialIdx, setTestimonialIdx] = useState(0);
  const [emailSent, setEmailSent] = useState(false);

  return (
    <div className="home-wrapper">
      <style>
        {`
          /* Mobile-first padding and centering */
          .page-container {
            padding: 0 20px; /* Gives you that nice breathing room on the sides */
            max-width: 1200px; /* Prevents it from getting too wide on huge monitors */
            margin: 0 auto; /* Centers the content */
            width: 100%;
            box-sizing: border-box;
          }

          /* Optional: Slightly larger padding for desktop */
          @media (min-width: 768px) {
            .page-container {
              padding: 0 40px;
            }
          }
        `}
      </style>

      {/* Hero might need to be full width depending on your design, 
          but usually text needs padding! */}
      <div className="page-container">
        <Hero scrollTo={scrollTo} />
      </div>

      {/* Kept Marquee outside so its background can span 100% of the screen */}
      <Marquee />

      {/* The rest of your content gets neatly padded */}
      <main className="page-container">
        <Collections
          activeCollection={activeCollection}
          setActiveCollection={setActiveCollection}
          setFilter={setFilter}
          scrollTo={scrollTo}
        />

        <Shop filter={filter} setFilter={setFilter} addToCart={addToCart} />

        <Craft />

        <Process />

        <Testimonials 
          testimonialIdx={testimonialIdx} 
          setTestimonialIdx={setTestimonialIdx} 
        />

        <FAQ faqOpen={faqOpen} setFaqOpen={setFaqOpen} />

        <FinalCTA emailSent={emailSent} setEmailSent={setEmailSent} />
      </main>
    </div>
  );
}
